INSERT INTO `v1_6b8bcd1b764667f9784382a27f8c4d4fee8d479e68117c4972a20f4cd2404793` VALUES (111031, "", "存外意義あるものだ\n資材ダイビングとか\nいう新種の探索行は", "", 13020026, "", "", "", 11, 10, 302);
INSERT INTO `v1_6b8bcd1b764667f9784382a27f8c4d4fee8d479e68117c4972a20f4cd2404793` VALUES (0, "", 1, "", 13020027, "", "", "", 91, "", 302);
INSERT INTO `v1_6b8bcd1b764667f9784382a27f8c4d4fee8d479e68117c4972a20f4cd2404793` VALUES (111031, "", "まあ万一溺れたとて\n後輩たちの誰ぞが\nきっと気付くだろう", "", 13020028, "", "", "", 11, 10, 302);
INSERT INTO `v1_6b8bcd1b764667f9784382a27f8c4d4fee8d479e68117c4972a20f4cd2404793` VALUES (0, "", 1, "", 13020029, "", "", "", 91, "", 302);
